<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api, items } from '../api';
import TechnicalDetails from '../TechnicalDetails.vue';
import { statusText } from '../present';
import { filePayload, lines, pathId, safeJson } from './common';
const busy=ref(false),error=ref(''),notice=ref(''), connections=ref<any[]>([]), intents=ref<any[]>([]),rules=ref<any[]>([]), preview=ref<any>(), sendBlocked=ref(false);
const grants=ref<any[]>([]), grant=ref({connectionId:'',principalId:'',profileId:'',taskId:'',workflowId:'',enabled:false});
const account=ref(''),accountConfirmed=ref(false);
const label=ref(''),clientId=ref(''),clientSecret=ref(''),redirectUri=ref(''),password=ref(''),confirmDelete=ref(false);
const connectionId=ref(''),to=ref(''),cc=ref(''),bcc=ref(''),subject=ref(''),plainText=ref(''),html=ref(''),taskId=ref(''),attachments=ref<any[]>([]),upload=ref<File>();
const rule=ref({connectionId:'',profileId:'',workflowId:'',templateId:'',templateHash:'',recipients:'',domains:'',minIntervalMs:0,dailyLimit:1,expiresAt:'',forbiddenTypes:'',enabled:false});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'请求失败';}finally{busy.value=false;}}
async function refresh(){const all=await Promise.allSettled([api('app-connections').then(v=>connections.value=items(v)),api('action-intents').then(v=>intents.value=items(v)),api('app-rules').then(v=>rules.value=items(v)),api('app-grants').then(v=>grants.value=items(v))]);const failure=all.find(x=>x.status==='rejected') as PromiseRejectedResult|undefined;if(failure)throw failure.reason;}
async function createConnection(){await run(async()=>{try{await api('app-connections','POST',{provider:'gmail',label:label.value,account:account.value,accountConfirmed:accountConfirmed.value,clientId:clientId.value,clientSecret:clientSecret.value,redirectUri:redirectUri.value});clientSecret.value='';await refresh();notice.value='连接配置已保存。';}finally{clientSecret.value='';}});}
async function start(id:string){await run(async()=>{const result=await api(`app-connections/${pathId(id)}/oauth/start`,'POST',{});const url=new URL(result.authorizationUrl);if(url.protocol!=='https:'||url.hostname!=='accounts.google.com')throw new Error('授权地址无效');window.location.assign(url.toString());});}
async function testConnection(id:string){await run(async()=>{const result=await api(`app-connections/${pathId(id)}/test`,'POST',{});await refresh();notice.value=`服务端测试结果：${result?.status ?? '请查看连接状态'}`;});}
async function remove(id:string){await run(async()=>{if(!password.value||!confirmDelete.value)throw new Error('请输入密码并确认删除');try{await api(`app-connections/${pathId(id)}`,'DELETE',{password:password.value,confirm:true});await refresh();notice.value='服务端已处理删除请求，请检查连接状态。';}finally{password.value='';confirmDelete.value=false;}});}
async function uploadFile(){await run(async()=>{const f=upload.value;if(!f)throw new Error('请选择附件');const allowed=['text/plain','text/csv','application/json','application/pdf','image/png','image/jpeg'];if(f.size>8*1024*1024||!allowed.includes(f.type))throw new Error('附件须不超过 8 MiB，且为文本、CSV、JSON、PDF、PNG 或 JPEG');const data=await filePayload(f);const result=await api('artifacts','POST',{filename:f.name,mimeType:f.type,...data});attachments.value.push(result);upload.value=undefined;notice.value='附件已上传。';});}
async function propose(){await run(async()=>{const input={to:lines(to.value),cc:lines(cc.value),bcc:lines(bcc.value),subject:subject.value,plainText:plainText.value,...(html.value?{html:html.value}:{}),attachments:attachments.value.map(a=>({artifactId:a.id,filename:a.filename}))};const result=await api('action-intents','POST',{connectionId:connectionId.value,action:'gmail.send_email',input,...(taskId.value?{taskId:taskId.value}:{})});await refresh();await openPreview(result.id);notice.value='已提交本地待审批意图，尚未发送。';});}
async function openPreview(id:string){preview.value=await api(`action-intents/${pathId(id)}/decision`);const status=currentIntent()?.status;if (['CONFIRMED','FAILED','CANCELLED','SEND_UNCERTAIN'].includes(status)) sessionStorage.removeItem('v11-send-pending:'+id);sendBlocked.value=sessionStorage.getItem('v11-send-pending:'+id)==='1';}
function currentIntent(){return preview.value?.intent ?? preview.value;}
async function decision(value:'APPROVED'|'REJECTED'){await run(async()=>{const i=currentIntent();if(!i?.id||!i.inputHash)throw new Error('缺少服务端审批哈希');await api(`action-intents/${pathId(i.id)}/decision`,'POST',{decision:value,inputHash:i.inputHash});await refresh();await openPreview(i.id);notice.value='服务端已记录决定。';});}
async function send(){await run(async()=>{const i=currentIntent();if(!i?.id||!i.inputHash||i.status!=='APPROVED'||sendBlocked.value)throw new Error('当前状态不允许发送');if(!window.confirm('确认发送此已审批邮件？'))return;sendBlocked.value=true;sessionStorage.setItem('v11-send-pending:'+i.id,'1');try{await api(`action-intents/${pathId(i.id)}/send`,'POST',{inputHash:i.inputHash});await refresh();await openPreview(i.id);notice.value='请以服务端状态为准。';}catch(e){sendBlocked.value=true;throw new Error('发送结果未确认。请刷新状态并人工核对，切勿重试：'+(e instanceof Error?e.message:''));}});}
async function cancel(){await run(async()=>{const id=currentIntent()?.id;if(!id)throw new Error('请选择意图');await api(`action-intents/${pathId(id)}/cancel`,'POST',{});await refresh();await openPreview(id);notice.value='服务端已处理取消请求。';});}
function draftRule(){const i=currentIntent(), p=preview.value?.proposal, mail=p?.mail;if(!i || !mail || !preview.value?.templateHash)throw new Error('审批快照或模板哈希不可用');rule.value={...rule.value,connectionId:i.connectionId,profileId:i.profileId,workflowId:i.workflowId,templateId:i.templateId,templateHash:preview.value.templateHash,recipients:[...(mail.to??[]),...(mail.cc??[]),...(mail.bcc??[])].join(', '),domains:'',enabled:false};notice.value='规则草稿已填入，请检查限制并保存。';}
async function createGrant(){await run(async()=>{await api('app-grants','POST',{...grant.value});await refresh();notice.value='授权已保存。';});}
async function toggleGrant(g:any){await run(async()=>{await api('app-grants/'+pathId(g.id),'PATCH',{enabled:!g.enabled});await refresh();});}
async function createRule(){await run(async()=>{const r=rule.value;const expiresAt=new Date(r.expiresAt).getTime();if(!Number.isFinite(expiresAt))throw new Error('请选择规则有效期');await api('app-rules','POST',{connectionId:r.connectionId,profileId:r.profileId,workflowId:r.workflowId,templateId:r.templateId,templateHash:r.templateHash,recipients:lines(r.recipients),domains:lines(r.domains),minIntervalMs:Number(r.minIntervalMs),dailyLimit:Number(r.dailyLimit),expiresAt,forbiddenTypes:lines(r.forbiddenTypes),enabled:r.enabled});await refresh();notice.value='规则已提交。';});}
async function toggleRule(r:any){await run(async()=>{await api('app-rules/'+pathId(r.id),'PATCH',{enabled:!r.enabled});await refresh();});}
onMounted(()=>run(refresh));
</script>
<template><div :aria-busy="busy"><p v-if="busy" role="status">正在处理…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section><h3>Gmail 连接</h3><p>需要 Google OAuth 配置和白名单 HTTPS 回调。gmail.send 是 Sensitive 权限；此权限不包含读取邮箱。公开应用可能需要 Google 审核。</p>
<label>连接名称<input v-model="label"></label><label>发送邮箱地址<input v-model="account" type="email" autocomplete="email"></label><label><input v-model="accountConfirmed" type="checkbox">我确认此地址属于授权账号或其已验证别名。标签不是 Google 身份验证结果。</label><label>OAuth Client ID<input v-model="clientId"></label><label>OAuth Client Secret<input v-model="clientSecret" type="password" autocomplete="off"></label><label>HTTPS 回调地址<input v-model="redirectUri" type="url"></label><button :disabled="busy" @click="createConnection">保存连接配置</button><button :disabled="busy" @click="run(refresh)">刷新状态</button>
<article v-for="c in connections" :key="c.id"><h4>{{ c.label ?? c.account ?? c.id }}</h4><p>状态：{{ statusText(c.status) }} · 权限：{{ (c.scopes ?? []).join(', ') }}</p><button :disabled="busy" @click="start(c.id)">连接并授权</button><button :disabled="busy" @click="testConnection(c.id)">测试连接</button><button :disabled="busy || !confirmDelete" @click="remove(c.id)">删除此账号</button></article><label>删除账号的管理员密码<input v-model="password" type="password" autocomplete="current-password"></label><label><input v-model="confirmDelete" type="checkbox">确认删除所选账号</label></section>
<section><h3>本地邮件草稿</h3><p>这是本系统的待发送意图，并非 Gmail 云端草稿。提交后必须检查服务端预览。</p><label>发送账号<select v-model="connectionId"><option value="">请选择</option><option v-for="c in connections" :key="c.id" :value="c.id">{{ c.label ?? c.account ?? c.id }} · {{ statusText(c.status) }}</option></select></label><label>收件人 To（逗号或换行分隔）<textarea v-model="to"></textarea></label><label>抄送 Cc<textarea v-model="cc"></textarea></label><label>密送 Bcc<textarea v-model="bcc"></textarea></label><label>主题<input v-model="subject"></label><label>纯文本正文<textarea v-model="plainText"></textarea></label><label>HTML 正文（可选）<textarea v-model="html"></textarea></label><label>任务 ID（可选）<input v-model="taskId"></label><label>受管附件（最大 8 MiB）<input type="file" accept=".txt,.csv,.json,.pdf,.png,.jpg,.jpeg,text/plain,text/csv,application/json,application/pdf,image/png,image/jpeg" @change="upload=($event.target as HTMLInputElement).files?.[0]"></label><button :disabled="busy || !upload" @click="uploadFile">上传附件</button><ul><li v-for="a in attachments" :key="a.id">{{ a.filename }} · {{ a.sha256 }} <button :disabled="busy" @click="attachments=attachments.filter(x=>x.id!==a.id)">移除附件</button></li></ul><button :disabled="busy" @click="propose">提交草稿供审核</button></section>
<section><h3>发送历史与审批</h3><ul><li v-for="i in intents" :key="i.id"><button :disabled="busy" @click="run(()=>openPreview(i.id))">{{ i.id }} · {{ statusText(i.status) }}</button></li></ul><template v-if="preview"><p>以下为服务端保存的完整审批快照。改变内容或账号需要新意图及重新审批。</p><TechnicalDetails :value="preview" label="审批快照（技术详情）" /><p v-if="currentIntent().status==='SEND_UNCERTAIN' || sendBlocked" role="alert">发送结果不确定。请先人工核对，不能重试此意图。</p><button :disabled="busy || !preview.proposal || !preview.templateHash" @click="run(async()=>draftRule())">从预览生成规则草稿</button><button :disabled="busy || currentIntent().status!=='WAITING_APPROVAL'" @click="decision('APPROVED')">批准此哈希</button><button :disabled="busy || currentIntent().status!=='WAITING_APPROVAL'" @click="decision('REJECTED')">拒绝</button><button :disabled="busy || sendBlocked || currentIntent().status!=='APPROVED'" @click="send">确认发送</button><button :disabled="busy || !['WAITING_APPROVAL','APPROVED'].includes(currentIntent().status)" @click="cancel">取消意图</button></template></section>
<section><h3>应用授权</h3><p>taskId 为 * 时，Owner 明确授予该 principal、profile 和 workflow 的未来任务发送权限。</p><label>授权连接 ID<input v-model="grant.connectionId"></label><label>授权 Principal ID<input v-model="grant.principalId"></label><label>授权 Profile ID<input v-model="grant.profileId"></label><label>授权任务 ID<input v-model="grant.taskId"></label><label>授权 Workflow ID<input v-model="grant.workflowId"></label><label><input v-model="grant.enabled" type="checkbox">启用此授权</label><button :disabled="busy" @click="createGrant">保存授权</button><article v-for="g in grants" :key="g.id"><TechnicalDetails :value="g" label="授权（技术详情）" /><p>状态：{{ g.enabled?'已启用':'已停用' }}</p><button :disabled="busy" @click="toggleGrant(g)">{{ g.enabled?'撤销授权':'启用授权' }}</button></article></section>
<section><h3>发送规则</h3><p>规则限制账号、工作流、模板、收件人、次数、间隔、有效期和禁止的附件类型。启用后，符合规则的草稿会自动发送。</p><label>连接 ID<input v-model="rule.connectionId"></label><label>Profile ID<input v-model="rule.profileId"></label><label>Workflow ID<input v-model="rule.workflowId"></label><label>模板 ID<input v-model="rule.templateId"></label><label>模板哈希<input v-model="rule.templateHash"></label><label>允许收件人<input v-model="rule.recipients"></label><label>允许域名<input v-model="rule.domains"></label><label>最短间隔（毫秒）<input v-model.number="rule.minIntervalMs" type="number" min="0"></label><label>每日上限<input v-model.number="rule.dailyLimit" type="number" min="1"></label><label>有效期至<input v-model="rule.expiresAt" type="datetime-local"></label><label>禁止附件类型（逗号分隔）<input v-model="rule.forbiddenTypes"></label><label><input v-model="rule.enabled" type="checkbox">启用规则</label><button :disabled="busy" @click="createRule">创建规则</button><article v-for="r in rules" :key="r.id"><TechnicalDetails :value="r" label="规则（技术详情）" /><button :disabled="busy" @click="toggleRule(r)">{{ r.enabled?'停用':'启用' }}</button></article></section></div></template>
